const byDomain = (letter) => SHOTS.filter((s) => s.id.startsWith(letter));
const byControl = (kind) => SHOTS.filter((s) => s.control === kind);

const countBy = (pred) => SHOTS.filter(pred).length;

// 唯一真值。md / JSON 顶部必须与这里一致；改矩阵后自检会红。
