// 自检：node docs/ui-audit-0801/shot-matrix.js
if (require.main === module) {
  const assert = require('assert');
  // ★ 路由体检(★放在统计断言之前:加一行会让 STATS 先炸,把路由问题遮住):矩阵里每条 route 都必须真有对应的 .wxml。
  //   页面被退役而矩阵没跟着改,拍出来的是编译错误图 —— 而截图脚本本身不会报错,
  //   于是「拍到了」和「拍对了」被混为一谈。假图会反向制造假 bug,比没图贵。
  //   2026-08-08 这条门禁一上来就抓到 7 条:E13/E14(#633 退役 merchant/official)、
  //   C31~C35(#607 把三页版商家报名并成一页)。
  {
    const fs = require('fs');
    const path = require('path');
    const xcxRoot = path.resolve(__dirname, '..');
    const dead = SHOTS
      .map((row) => ({ id: row.id, route: String(row.route || '').replace(/^\//, '').split('?')[0] }))
      .filter((row) => row.route && !fs.existsSync(path.join(xcxRoot, `${row.route}.wxml`)));
    assert.deepStrictEqual(dead, [],
      '矩阵引用了不存在的页面,拍出来会是编译错误图:' + dead.map((d) => `${d.id}→${d.route}`).join(', '));
  }

  const ids = SHOTS.map((s) => s.id);
  const files = SHOTS.map((s) => s.file);
  assert.strictEqual(new Set(ids).size, ids.length, '矩阵 id 有重复');
  assert.strictEqual(new Set(files).size, files.length, '截图文件名有重复');
  for (const s of SHOTS) {
    assert.ok(s.route.startsWith('/'), `${s.id} 路由不是绝对路径`);
    assert.ok(s.expect && s.expect.selector && s.expect.min >= 1, `${s.id} 缺少非恒真断言`);
    assert.ok(['player', 'merchant', 'club', 'guest'].includes(s.role), `${s.id} role 非法`);
    assert.ok(['P0', 'P1', 'P2'].includes(s.priority), `${s.id} priority 非法`);
    if (s.scrollTop !== undefined) assert.ok(Number.isFinite(s.scrollTop), `${s.id} scrollTop 非数字`);
  }
  // ★ 与上面那条死路由体检同理:这两条也必须**排在 STATS 断言之前**。
  //   STATS 是记账,改任何一行都会先炸在它上面,把真正的路由/棘轮问题遮住 ——
  //   2026-08-18 做负控实测到:删一行 F09,红的是 STATS 而不是「页面→矩阵」那条,
  //   把顺序调过来才看得见真判据。断言顺序即语义。
  // ★★ 反方向体检:app.json 里有、矩阵里没有。
  //
  // 上面那条死路由体检查的是「矩阵引用了不存在的页」(会拍出编译错误图),它 2026-08-08 抓到过 7 条。
  // 但它**只有一个方向**:新加了一页而矩阵没跟上,表现为「没有这一行」,而**没有的行不会报错**。
  // 2026-08-18 实测:自 20260810 那批以来新增 12 条路由,矩阵一行都没有,全量复核照跑会全绿然后漏 12 页。
  // 「门禁只有一个方向 = 另一个方向永远不会红」—— 本仓反复栽的同一个形状,这里把它补齐。
  // 判据实现只有一份(scripts/uiaudit/coverage-gate.js),这里复用,不在两处各写一套。
  {
    const { analyze } = require('./uiaudit/coverage-gate.js');
    const cov = analyze();
    assert.deepStrictEqual(cov.missing, [],
      'app.json 里有、矩阵里一行都没有的路由(全量复核会静默漏拍;补矩阵行,或在 '
      + 'scripts/uiaudit/coverage-exemptions.json 写明豁免理由)');
  }

  // ★ blocked 棘轮:条数只许减不许增。
  //
  // 不加这条,blocked 就是下一个「未判定」无限逃生口 —— 拍不出来的都标 blocked,矩阵永远绿。
  // 外锚是 scripts/uiaudit/blocked-baseline.json:它在仓库里、进 diff、要人评审。
  // 新增 blocked 必须**显式改那个文件**,改不动就说明这一条得想办法拍,而不是标一下就过。
  {
    const fs2 = require('fs');
    const path2 = require('path');
    const baseFile = path2.join(__dirname, 'uiaudit', 'blocked-baseline.json');
    const base = JSON.parse(fs2.readFileSync(baseFile, 'utf8'));
    const baseline = new Set(base.blockedIds || []);
    const nowBlocked = blocked().map((s) => s.id);
    const fresh = nowBlocked.filter((id) => !baseline.has(id));
    assert.deepStrictEqual(fresh, [],
      'blocked 只许减不许增。新增的 blocked:' + fresh.join(', ')
      + ' —— 要么把它拍出来,要么显式改 scripts/uiaudit/blocked-baseline.json 并说明理由');
    const healed = [...baseline].filter((id) => !nowBlocked.includes(id));
    if (healed.length) {
      console.log('提示:基线里 ' + healed.length + ' 条 blocked 已经不 blocked 了,收窄 blocked-baseline.json:' + healed.join(', '));
    }
  }

  // 统计断言：STATS 是 md / JSON 顶部引用的唯一真值，算出来对不上就红。
  const actual = {
    total: SHOTS.length,
    byPriority: { P0: countBy((s) => s.priority === 'P0'), P1: countBy((s) => s.priority === 'P1'), P2: countBy((s) => s.priority === 'P2') },
    blockedByPriority: {
      P0: countBy((s) => s.priority === 'P0' && s.blocked),
      P1: countBy((s) => s.priority === 'P1' && s.blocked),
      P2: countBy((s) => s.priority === 'P2' && s.blocked),
    },
    actionable: { P0: p0().length, P1: p1().length, P2: p2().length, total: p0().length + p1().length + p2().length },
    blocked: blocked().length,
    domains: { A: byDomain('A').length, B: byDomain('B').length, C: byDomain('C').length, D: byDomain('D').length, E: byDomain('E').length, F: byDomain('F').length },
    control: {
      setData: byControl('setData').length,
      'identity+setData': byControl('identity+setData').length,
      'real-data': byControl('real-data').length,
      'real-device': byControl('real-device').length,
    },
    fixtureVerified: countBy((s) => s.fixtureVerified),
  };
  assert.deepStrictEqual(actual, STATS, '统计与 STATS 不一致 —— 同步 STATS、md 顶部和 JSON 顶部三处');

  // 内部一致性：三个域计数之和、priority 之和都必须等于 total
  assert.strictEqual(Object.values(actual.domains).reduce((a, b) => a + b, 0), actual.total);
  assert.strictEqual(actual.byPriority.P0 + actual.byPriority.P1 + actual.byPriority.P2, actual.total);
  assert.strictEqual(actual.actionable.total + actual.blocked, actual.total);
  console.log(JSON.stringify(actual, null, 2));
  console.log('shot-matrix selftest OK — ' + SHOTS.length + ' 行;STATS 一致、死路由体检与覆盖率体检双向均通过、blocked 棘轮未增');
}
